<div class="page-heading"><h1><?= e($title) ?></h1><?php if (isRole('client','agent')): ?><a class="button" href="<?= e(url('location-form')) ?>">Nouvelle demande</a><?php endif ?></div>
<form method="get" class="filters compact panel"><input type="hidden" name="r" value="locations"><label>Statut<select name="statut"><option value="">Tous</option><?php foreach (App\Models\Location::STATUSES as $status): ?><option value="<?= e($status) ?>" <?= ($_GET['statut'] ?? '')===$status ? 'selected' : '' ?>><?= e(label($status)) ?></option><?php endforeach ?></select></label><button>Filtrer</button></form>
<div class="table-wrap"><table><thead><tr><th>Référence</th><th>Client</th><th>Équipement</th><th>Dates</th><th>Quantité</th><th>Total</th><th>Statut</th><th></th></tr></thead><tbody>
<?php foreach ($rows as $row): ?><tr><td>#<?= (int) $row['id'] ?></td><td><?= e($row['client_prenom'].' '.$row['client_nom']) ?></td><td><?= e($row['equipement']) ?></td><td><?= e(dateFr($row['date_debut'])) ?><br><?= e(dateFr($row['date_fin'])) ?></td><td><?= (int) $row['quantite'] ?></td><td><?= e(money(App\Models\Location::totalCents($row)/100)) ?></td><td><span class="status <?= e($row['statut']) ?>"><?= e(label($row['statut'])) ?></span></td><td><a href="<?= e(url('location',['id'=>$row['id']])) ?>">Consulter</a></td></tr><?php endforeach ?>
<?php if (!$rows): ?><tr><td colspan="8" class="empty">Aucune location pour le moment.</td></tr><?php endif ?>
</tbody></table></div>
